package com.hibernate.ecommerce.service;import com.hibernate.ecommerce.dto.ProductDTO;import com.hibernate.ecommerce.mapper.ProductMapper;import com.hibernate.ecommerce.model.Product;import com.hibernate.ecommerce.repository.OrderRepository;import com.hibernate.ecommerce.repository.ProductRepository;import org.springframework.stereotype.Service;import java.util.List;@Servicepublic class ProductService implements IProductService {    private final ProductRepository productRepository;    private final OrderRepository orderRepository;    public ProductService(ProductRepository productRepository, OrderRepository orderRepository) {        this.productRepository = productRepository;        this.orderRepository = orderRepository;    }    @Override    public ProductDTO addProduct(ProductDTO dto) {        if(dto == null) return null;        Product product = new Product();        product.setName(dto.getName());        product.setDescription(dto.getDescription());        product.setPrice(dto.getPrice());        product.setStock(dto.getStock());        Product save = productRepository.save(product);        return ProductMapper.toDTO(save);    }    @Override    public ProductDTO findProductById(Long id) {        return ProductMapper.toDTO(productRepository.findById(id)                .orElseThrow(RuntimeException::new));    }    @Override    public List<ProductDTO> findOptionalAll(String filterName) {        if (filterName.isBlank()){            List<Product> all = productRepository.findAll();            return all.stream()                    .map(ProductMapper::toDTO)                    .toList();        }else{            List<Product> filter = productRepository.findByName(filterName);            return filter.stream()                    .map(ProductMapper::toDTO)                    .toList();        }    }    @Override    public ProductDTO updateProduct(Long id, ProductDTO dto) {        if (dto == null) {            throw new IllegalArgumentException("ProductDTO cannot be null");        }        if (id == null) {            throw new IllegalArgumentException("Product id cannot be null");        }        Product search = productRepository.findById(id)                .orElseThrow(() -> new RuntimeException("Product not found with id: " + id));        if (dto.getName() != null) {            search.setName(dto.getName());        }        if (dto.getDescription() != null) {            search.setDescription(dto.getDescription());        }        if (dto.getPrice() != null) {            if (dto.getPrice() < 0) {                throw new RuntimeException("Price cannot be negative: " + dto.getPrice());            }            search.setPrice(dto.getPrice());        }        if (dto.getStock() != null) {            if (dto.getStock() < 0) {                throw new RuntimeException("Stock cannot be negative: " + dto.getStock());            }            search.setStock(dto.getStock());        }        Product save = productRepository.save(search);        return ProductMapper.toDTO(save);    }    @Override    public void deleteProduct(Long id) {        if(productRepository.existsById(id)){            if(orderRepository.existsOrderDetailByProductId(id)){                throw new IllegalStateException("The state of the product is not available for the operation");            }else{                productRepository.deleteById(id);            }        }    }}